  'section.detail.pobles.viquipedia.explica': 'A la ficha de este pueblo le faltan datos. Tu navegador puede traerlos de la Viquipèdia (la Wikipedia en catalán), Wikidata y Wikimedia Commons, que son públicas y libres. Hasta que no pulsas el botón no se conecta con nadie. Cuando lo pulsas, Wikimedia recibe el nombre del pueblo y tu dirección IP, sin cookies ni la dirección de esta página. Lo que traiga se guarda solo en este navegador, y no se escribe nada en el servidor de Sóc de Poble.',
