  'section.translations.option.gl': 'Interfaz en gallego',
  'section.translations.pages.title': 'Traductor de Pueblo para páginas',
  'section.translations.pages.lead': 'Traduce la página que estás leyendo sin salir de ella: con Apertium, software libre, y, para el euskera y el alemán, con MyMemory.',
  'section.translations.pages.card.title': 'Botón «Traduir» de la barra azul',
  /* Gauntlet 261030 (cicle 2, traductor-client) · La app nativa y los textos del Traductor de Pueblo. */
  'section.translations.pages.card.natiu': 'En la aplicación nativa, de momento, el botón todavía no traduce nada: si lo pulsas, te lo dice.',
  'section.traduir.menu': 'Traducir la página',
  'section.traduir.original': 'Original (valenciano)',
  'section.traduir.traduit': 'Traducido automáticamente del valenciano',
  'section.traduir.veureOriginal': 'Ver el original',
  'section.traduir.traduint': 'Traduciendo…',
  'section.traduir.avis.senseTraductor': 'La traducción automática no está disponible en este servidor.',
  'section.traduir.avis.error': 'No se ha podido traducir la página. Vuelve a intentarlo más tarde.',
  'section.traduir.avis.massaLlarga': 'Esta página es demasiado larga para traducirla automáticamente.',
  'section.traduir.avis.senseConnexio': 'No se ha podido conectar con el servicio de traducción.',
  'section.traduir.avis.senseText': 'Esta página no tiene texto que traducir.',
  'section.traduir.avis.limit': 'Se ha alcanzado el límite de traducciones automáticas. Vuelve a intentarlo más tarde.',
  'section.traduir.avis.ocupat': 'El servicio de traducción está ocupado. Vuelve a intentarlo dentro de un momento.',
  'section.translations.pages.card.body': 'El botón «Traduir» de la barra azul traduce la página al castellano, al gallego, al euskera, al inglés, al francés y al alemán. Para el castellano, el gallego, el inglés y el francés lo hace con Apertium, un traductor de software libre. Para el euskera y el alemán, que Apertium no ofrece desde el valenciano, lo hace con MyMemory, el servicio de la empresa italiana Translated, que no dice qué motor automático utiliza. Solo cuando eliges una lengua, el texto de la página sale hacia el traductor: en socdepoble.org, desde tu navegador directamente al servicio, que ve tu dirección IP; en un sitio con servidor propio, como WordPress, a través de ese servidor, que puede tener configurado otro proveedor. MyMemory puede guardar los textos que recibe y registrar la dirección IP, y el euskera y el alemán tienen un límite diario de traducciones. Por eso solo se traduce el texto de las páginas públicas, nunca tus mensajes ni tus notas. Donde no hay traducción, el botón lo indica.',
  'section.translations.dynamic.title': 'Traducción dinámica de tarjetas',
  'section.translations.dynamic.lead': 'Cómo funciona la traducción del contenido creado por los usuarios de otros pueblos.',
  'section.translations.engine.title': 'Motor de traducción integrado',
  'section.translations.engine.body': 'Además del idioma base de la interfaz, las Tarjetas (Muro, Chats, Mercado y Eventos) contarán con un motor de traducción automática. Te permitirá leer al instante lo que escriben usuarios de otros pueblos del estado (por ejemplo, si alguien publica en euskera o en gallego) traduciéndolo a tu lengua de preferencia.',
  'section.translations.howto.title': 'Cómo usarlo',
  'section.translations.howto.body': 'Busca el icono de traducción dentro de las publicaciones de las tarjetas: servirá para traducir solo ese mensaje o publicación concreta. Mientras la traducción de tarjetas no esté conectada, el botón lleva a esta página.',
  'section.translations.note.title': 'Nota',
  'section.translations.note.body': 'Las traducciones automáticas pueden contener pequeños errores de interpretación cuando se trata de expresiones muy locales o frases hechas de cada territorio.',
