  'section.connectar.titular.intro': '{nom} es titular de {entitat} y ha elegido que se vea aquí.',
  'section.connectar.lead': 'Elige dónde llega (por defecto, a la Safata d’Entrada), quién puede verlo y cómo lo encontrarás después.',
  'section.connectar.leadCamins': 'Cada camino tiene su botón: conectar con alguien o escribirle no te hace miembro de nada. Si guardas el elemento en tus notas en privado, no avisa a nadie; si eliges personas o grupos de chat, les enviaremos el enlace.',
