  'section.perfil.privacitat.dades.natiu': 'Tus datos ya están preparados. Dentro de la app no se pueden guardar solos en las descargas: guárdalos tú como {nom}.',
  'section.perfil.privacitat.dades.compartix': 'Compartir el archivo',
  'section.perfil.privacitat.dades.copia': 'Copiar el texto',
  'section.perfil.privacitat.dades.text': 'Tus datos, en JSON',
  'section.perfil.privacitat.dades.textAjuda': 'Si no puedes compartir el archivo ni copiar el texto con el botón, selecciónalo aquí y pégalo en una nota o un correo.',
  'section.perfil.privacitat.dades.compartit': 'Hecho: has enviado el archivo {nom} desde el menú de compartir.',
  'section.perfil.privacitat.dades.errorCompartir': 'No se ha podido compartir el archivo. Copia su texto y guárdalo tú.',
  'section.perfil.privacitat.dades.copiat': 'Texto copiado. Pégalo en una nota o un correo y guárdalo como {nom}.',
  'section.perfil.privacitat.dades.errorCopiar': 'No se ha podido copiar el texto. Selecciónalo en el recuadro y cópialo tú.',
  'section.perfil.privacitat.pagina.titol': 'Privacidad y datos',
  'section.perfil.privacitat.pagina.lead': 'Tus derechos sobre lo que guardamos: una copia de los datos, el consentimiento y la baja.',
  'section.perfil.privacitat.pagina.buit': 'Este nodo todavía no ofrece ninguna de estas opciones.',
  'section.perfil.privacitat.dades.titol': 'Mis datos',
  'section.perfil.privacitat.dades.explica': 'Descarga una copia de los datos que Sóc de Poble guarda de tu cuenta: perfil, organizaciones, publicaciones, notas, conversaciones, la lista de tus archivos y adjuntos, consentimientos, las denuncias que has hecho, las personas y entidades que has bloqueado o que sigues y las normas que has aceptado. Para proteger a otras personas, no indicamos quién te ha denunciado, quién te ha bloqueado ni quién te sigue: de las denuncias sobre ti solo consta cuántas han terminado con una medida (si quieres el detalle, pídenoslo por correo) y, de quien te sigue, cuántas personas son. Tampoco incluimos las huellas de la dirección IP ni el permiso cifrado de Apple. Es un archivo JSON que puedes abrir con cualquier editor de texto.',
  'section.perfil.privacitat.dades.fet': 'Ya tienes el archivo {nom} en las descargas.',
  'section.perfil.privacitat.dades.descarrega': 'Descargar mis datos',
  'section.perfil.privacitat.dades.error': 'No se han podido preparar tus datos. Vuelve a intentarlo.',
  'section.perfil.privacitat.politica.llegir': 'Leer la política',
  'section.perfil.privacitat.politica.oblitRuralResum': 'Olvido Saludable Rural: la memoria histórica de Sóc de Poble, El Rentonar y la Coordinadora d’Estudis Eòlics del Comtat, junto con las publicaciones fijadas y los marcadores, queda siempre blindada y nunca caduca.',
  'section.perfil.privacitat.consentiment.titol': 'Consentimiento',
