  'section.perfil.privacitat.consentiment.errorLectura': 'No se ha podido leer el estado del consentimiento.',
  'section.perfil.privacitat.consentiment.errorRegistre': 'No se ha podido registrar el consentimiento.',
  'section.perfil.privacitat.consentiment.errorRetirada': 'No se ha podido retirar el consentimiento.',
  'section.perfil.privacitat.consentiment.senseConstancia': 'No consta que hayas aceptado la política de privacidad.',
  'section.perfil.privacitat.consentiment.acceptada': 'La aceptaste (versión {versio}) el {data}.',
  'section.perfil.privacitat.consentiment.retirada': 'La retiraste el {data}.',
  'section.perfil.privacitat.consentiment.vigent': 'Política de privacidad vigente: versión {versio}.',
  'section.perfil.privacitat.consentiment.senseVigent': 'Todavía no hay ninguna política de privacidad publicada.',
  'section.perfil.privacitat.consentiment.calTitol': 'Necesitamos tu consentimiento',
  'section.perfil.privacitat.consentiment.accepta': 'Aceptar la versión {versio}',
  'section.perfil.privacitat.consentiment.calText': 'Sin aceptar la política vigente no apareces en el padrón del pueblo.',
  'section.perfil.privacitat.consentiment.retira': 'Retirar el consentimiento',
  'section.perfil.privacitat.consentiment.retiraDescripcio': 'Dejarás de aparecer en el padrón del pueblo hasta que lo vuelvas a aceptar.',
  'section.perfil.privacitat.consentiment.retiraConfirma': 'Retirarlo',
  'section.perfil.privacitat.consentiment.retiraText': 'La cuenta no se borra: para eso, pide la baja. El registro de cuándo lo has dado y retirado se conserva, porque la ley nos obliga a poder demostrarlo.',
  'section.perfil.privacitat.baixa.titol': 'Darse de baja',
  'section.perfil.privacitat.baixa.comprovant': 'Comprobando el estado de la cuenta…',
  'section.perfil.privacitat.baixa.errorLectura': 'No se ha podido comprobar si tienes una baja pendiente.',
  'section.perfil.privacitat.baixa.errorDemanda': 'No se ha podido solicitar la baja.',
  'section.perfil.privacitat.baixa.cancelada': 'Baja cancelada. Tu perfil vuelve a ser como era.',
  'section.perfil.privacitat.baixa.errorCancela': 'No se ha podido cancelar la baja.',
  'section.perfil.privacitat.baixa.pendentTitol': 'Tienes una baja pendiente',
  'section.perfil.privacitat.baixa.cancela': 'Cancelar la baja',
  'section.perfil.privacitat.baixa.pendent': 'La solicitaste el {demanada}. La cuenta, tus publicaciones personales y tus archivos se borrarán definitivamente el {purga}, salvo los archivos que todavía usa una entidad (su ficha o una publicación) o una publicación de otra persona. {apple}',
  'section.perfil.privacitat.baixa.esperaApple': 'Si entraste con Apple y todavía no hemos podido retirar el permiso, el borrado puede esperar hasta {diesApple} días más.',
  'section.perfil.privacitat.baixa.explica': 'Si te vas, en el momento ocultamos tu perfil: deja de aparecer en el padrón, ponemos un nombre genérico en lugar del tuyo y le quitamos la foto. Tienes {dies} días para arrepentirte. Pasado ese plazo, se borran para siempre la cuenta, tus publicaciones personales y tus archivos, salvo los que todavía usa una entidad (su ficha o una publicación) o una publicación de otra persona; lo que publicaste en nombre de una entidad se queda en la entidad. {apple}',
  'section.perfil.privacitat.baixa.boto': 'Darme de baja',
  'section.perfil.privacitat.baixa.dialegTitol': 'Darte de baja',
  'section.perfil.privacitat.baixa.dialegDescripcio': 'Tienes {dies} días de gracia para echarte atrás.',
  'section.perfil.privacitat.baixa.confirma': 'Sí, darme de baja',
  'section.perfil.privacitat.baixa.punt.amaga': 'Ahora mismo ocultamos tu perfil: deja de aparecer en el padrón, ponemos un nombre genérico en lugar del tuyo y le quitamos la foto, y tus publicaciones dejan de mostrar tu nombre y tu foto.',
  'section.perfil.privacitat.baixa.punt.cancela': 'Durante {dies} días puedes cancelarla: entra de nuevo como siempre (con el correo, Apple o Google), ve a «Privacidad y datos» y pulsa «Cancelar la baja».',
  'section.perfil.privacitat.baixa.punt.apple': 'Si entraste con Apple, al solicitar la baja intentamos retirar el permiso que diste a Sóc de Poble; si no lo conseguimos, puedes retirarlo tú en Ajustes › tu nombre › Iniciar sesión con Apple, o en account.apple.com. Si cuando pasen los {dies} días todavía no lo hemos podido retirar, el borrado definitivo puede esperar hasta {diesApple} días más. Si lo hemos retirado y vuelves a entrar con Apple para cancelar la baja, Apple te volverá a pedir permiso.',
  'section.perfil.privacitat.baixa.punt.esborrat': 'Pasados los {dies} días, se borran definitivamente la cuenta, tus publicaciones personales y tus archivos, salvo los que todavía usa una entidad (su ficha o una publicación) o una publicación de otra persona. Lo que publicaste en nombre de una entidad se queda en la entidad.',
  'section.perfil.privacitat.baixa.punt.conserva': 'Se guardan, ya sin tu cuenta pero no del todo anónimas, la prueba del consentimiento, que la ley nos obliga a conservar, y, para el historial de moderación, las denuncias que hiciste y las que otras personas han hecho sobre ti o sobre tu contenido, con el identificador interno que tenía tu cuenta.',
  'section.perfil.privacitat.baixa.punt.sessio': 'Se cerrará la sesión en todos tus dispositivos.',
  'section.perfil.privacitat.baixa.motiu': '¿Por qué te vas? (opcional)',
  'section.perfil.privacitat.baixa.motiuAjuda': 'Nos ayuda a mejorar. Como máximo 500 caracteres.',
