  'section.xat.xifratge.avisFil': "Los mensajes y los archivos de este chat se cifran en tu dispositivo antes de salir. Al servidor de Sóc de Poble solo llegan cifrados y no tenemos las claves para abrirlos. Sí vemos quién habla con quién y cuándo. Comprobad el número de seguridad para estar seguros.",
  'section.xat.xifratge.avisFilPersonal': "Los mensajes y los archivos de este chat se cifran en tu dispositivo antes de salir. Al servidor de Sóc de Poble solo llegan cifrados y no tenemos las claves para abrirlos. Sí vemos cuándo escribes. En un chat solo tuyo no hay ningún número de seguridad que comparar.",
