  'page.avisador.intro': "L’Avisador envía un mensaje vecinal al chat cuando pasan las horas que has elegido sin actividad en esta app. El contador se pausa durante el descanso nocturno.",
  'page.avisador.limitacions': "Funciona con la sesión personal abierta, mientras la app puede ejecutarse y tiene conexión con el chat. Los ajustes se guardan en este dispositivo. Si la app está cerrada o suspendida, el dispositivo está apagado o el chat no está disponible, es posible que el aviso no llegue. Al volver a abrir la app, L’Avisador espera unos minutos antes de avisar. En caso de emergencia, llama al 112. L’Avisador no sustituye a la teleasistencia médica homologada.",
